#include <bits/stdc++.h>
using namespace std;

struct Rect {
    long long x1, y1, x2, y2;
};

long long intersectionArea(const vector<Rect>& rects) {
    long long x1 = LLONG_MIN, y1 = LLONG_MIN;
    long long x2 = LLONG_MAX, y2 = LLONG_MAX;

    for (const Rect& r : rects) {
        x1 = max(x1, r.x1);
        y1 = max(y1, r.y1);
        x2 = min(x2, r.x2);
        y2 = min(y2, r.y2);
    }

    return max(0LL, x2 - x1) * max(0LL, y2 - y1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Rect a, b, c;
    cin >> a.x1 >> a.y1 >> a.x2 >> a.y2;
    cin >> b.x1 >> b.y1 >> b.x2 >> b.y2;
    cin >> c.x1 >> c.y1 >> c.x2 >> c.y2;

    long long area = (a.x2 - a.x1) * (a.y2 - a.y1);
    long long covered = intersectionArea({a, b})
                      + intersectionArea({a, c})
                      - intersectionArea({a, b, c});

    cout << (covered < area ? "YES\n" : "NO\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Rect {
    long long x1, y1, x2, y2;
};

long long intersectionArea(const Rect& a, const Rect& b) {
    long long width = max(0LL, min(a.x2, b.x2) - max(a.x1, b.x1));
    long long height = max(0LL, min(a.y2, b.y2) - max(a.y1, b.y1));
    return width * height;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Rect a, b, c;
    cin >> a.x1 >> a.y1 >> a.x2 >> a.y2;
    cin >> b.x1 >> b.y1 >> b.x2 >> b.y2;
    cin >> c.x1 >> c.y1 >> c.x2 >> c.y2;

    Rect bc{
        max(b.x1, c.x1),
        max(b.y1, c.y1),
        min(b.x2, c.x2),
        min(b.y2, c.y2)
    };

    long long totalArea = (a.x2 - a.x1) * (a.y2 - a.y1);
    long long coveredArea = intersectionArea(a, b) + intersectionArea(a, c);

    if (bc.x1 < bc.x2 && bc.y1 < bc.y2)
        coveredArea -= intersectionArea(a, bc);

    cout << (coveredArea < totalArea ? "YES\n" : "NO\n");
    return 0;
}

