    long long height = max(0LL, min(a.y2, b.y2) - max(a.y1, b.y1));
    return width * height;
}

Rectangle intersection(const Rectangle& a, const Rectangle& b) {
    return {
        max(a.x1, b.x1),
        max(a.y1, b.y1),
        min(a.x2, b.x2),
        min(a.y2, b.y2)
    };
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Rectangle white, black1, black2;
    cin >> white.x1 >> white.y1 >> white.x2 >> white.y2;
    cin >> black1.x1 >> black1.y1 >> black1.x2 >> black1.y2;
    cin >> black2.x1 >> black2.y1 >> black2.x2 >> black2.y2;

    long long whiteArea =
        (white.x2 - white.x1) * (white.y2 - white.y1);

    long long coveredArea =
        intersectionArea(white, black1) +
        intersectionArea(white, black2) -
        intersectionArea(intersection(white, black1), black2);

    cout << (coveredArea < whiteArea ? "YES\n" : "NO\n");
    return 0;
}

